/// A blocking round trip, bounded by `bound` from when the request is written or queued: past it the
/// supervisor counts as stuck and the generation dies.
pub(super) fn call(&self, want: Want, id: u64, msg: impl FnOnce(u64) -> Msg, fds: Vec<Pipe>) -> Reply {
    let (tx, rx) = mpsc::sync_channel(1);
    self.request(want, id, Class::Normal, Waiter::Sync(tx), msg, fds)?;
    match rx.recv_timeout(self.bound) {
        Ok(reply) => reply,
        Err(mpsc::RecvTimeoutError::Timeout) => {
            let ms = self.bound.as_millis();
            self.die(format!("it did not answer a {} request within {ms} ms", want.name()));
            Err(self.gone())
        }
        Err(mpsc::RecvTimeoutError::Disconnected) => Err(self.gone()),
    }
}

let set = |p: &PathBuf, mode: u32| std::fs::set_permissions(p, std::fs::Permissions::from_mode(mode)).unwrap();
let d = dir("trust");
set(&d, 0o755);
assert!(trusted(&d), "an own directory, 0755, with no supervisor in it");
std::fs::write(d.join(EXE), b"").unwrap();
set(&d.join(EXE), 0o755);
assert!(trusted(&d), "an own directory and binary, both 0755");
set(&d.join(EXE), 0o777);
assert!(!trusted(&d), "a binary anybody can overwrite");
set(&d.join(EXE), 0o755);
for mode in [0o777, 0o775, 0o1777] {
    set(&d, mode);
    assert!(!trusted(&d), "a directory with mode {mode:o}");
}
assert!(!trusted(&d.join("missing")), "a directory that does not exist");

/// supervisor. Trusted: the directory, and the supervisor in it if present, belong to this user or to root and are
/// writable by neither group nor others. Root counts as an owner because a system-wide install (`sudo npm i -g`) is
/// owned by root, and only root could plant a binary there.
#[cfg(unix)]
pub(super) fn trusted(dir: &Path) -> bool {
    use std::os::unix::fs::MetadataExt;
    // SAFETY: geteuid has no preconditions and cannot fail.
    let me = unsafe { libc::geteuid() };
    let safe = |p: &Path| match std::fs::metadata(p) {
        Ok(m) => (m.uid() == me || m.uid() == 0) && m.mode() & 0o022 == 0,
        Err(e) => e.kind() == std::io::ErrorKind::NotFound && p != dir,
    };
    safe(dir) && safe(&dir.join(EXE))
}
